<section class="page-hero compact"><div class="container reveal"><span class="eyebrow">LATEST FROM 97 FOUNDATION</span><h1>News & Blog</h1><p>Foundation announcements, community updates, educational articles and stories of positive action.</p><div class="post-filters"><a class="<?=($type??'')===''?'active':''?>" href="<?=url('news')?>" data-spa-link>All</a><a class="<?=($type??'')==='news'?'active':''?>" href="<?=url('news?type=news')?>" data-spa-link>News</a><a class="<?=($type??'')==='blog'?'active':''?>" href="<?=url('news?type=blog')?>" data-spa-link>Blog</a></div></div></section><section class="section"><div class="container"><div class="public-post-grid"><?php foreach($posts as $p):?><article class="public-post-card reveal"><a class="public-post-image" href="<?=url('news/'.$p['slug'])?>" data-spa-link><?php if($p['featured_image']):?><img src="<?=e(public_upload($p['featured_image']))?>" alt="<?=e($p['title'])?>" loading="lazy"><?php else:?><div>97</div><?php endif;?><span><?=e(strtoupper($p['post_type']))?></span></a><div><small><?=e(date('d M Y',strtotime($p['published_at'])))?></small><h2><a href="<?=url('news/'.$p['slug'])?>" data-spa-link><?=e($p['title'])?></a></h2><p><?=e($p['excerpt']?:mb_strimwidth(strip_tags($p['content']??''),0,150,'…'))?></p><a class="text-link" href="<?=url('news/'.$p['slug'])?>" data-spa-link>Read More →</a></div></article><?php endforeach;?><?php if(!$posts):?><div class="empty-state premium-empty">No published news or blog posts yet.</div><?php endif;?></div></div></section>
